def wrap(body):
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 96 96"><rect width="96" height="96" rx="18" fill="#eef1ec"/><ellipse cx="48" cy="82" rx="30" ry="5" fill="#000" opacity=".08"/>{body}</svg>'
R=lambda x,y,w,h,f,rx=0,s=None,sw=0:f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{rx}" fill="{f}"'+(f' stroke="{s}" stroke-width="{sw}"' if s else '')+'/>'
C=lambda x,y,r,f,s=None,sw=0:f'<circle cx="{x}" cy="{y}" r="{r}" fill="{f}"'+(f' stroke="{s}" stroke-width="{sw}"' if s else '')+'/>'
E=lambda x,y,rx,ry,f,s=None,sw=0:f'<ellipse cx="{x}" cy="{y}" rx="{rx}" ry="{ry}" fill="{f}"'+(f' stroke="{s}" stroke-width="{sw}"' if s else '')+'/>'
P=lambda d,f,s=None,sw=0,extra='':f'<path d="{d}" fill="{f}"'+(f' stroke="{s}" stroke-width="{sw}" stroke-linejoin="round" stroke-linecap="round"' if s else '')+extra+'/>'
L=lambda x1,y1,x2,y2,s,sw=3:f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="{s}" stroke-width="{sw}" stroke-linecap="round"/>'
def gear(cx,cy,r,teeth,f,hole=None):
    pts=[]
    for i in range(teeth*2):
        a=math.pi*i/teeth;rr=r if i%2==0 else r*.78
        for da in (-.18,.18):
            pts.append((cx+rr*math.cos(a+da*math.pi/teeth*2),cy+rr*math.sin(a+da*math.pi/teeth*2)))
    d='M'+' L'.join(f'{x:.1f},{y:.1f}' for x,y in pts)+'Z'
    return P(d,f)+C(cx,cy,hole or r*.32,'#eef1ec')
def drum(x,y,w,h,f,band=DK):return R(x,y,w,h,f,4)+R(x,y+h*.3,w,3,band)+R(x,y+h*.65,w,3,band)+E(x+w/2,y+2,w/2,3,f)
def jerry(f):return P('M28 30 L56 22 L68 26 L68 76 L28 76 Z',f,DK,2)+R(56,16,8,8,DK,2)+P('M34 40 L60 34 M34 58 L60 52',None if False else 'none',DK,2)
def bottle(x,f,h=46):return P(f'M{x-6} 78 L{x-6} {78-h+14} Q{x-6} {78-h+6} {x-2} {78-h+2} L{x-2} {78-h-6} L{x+2} {78-h-6} L{x+2} {78-h+2} Q{x+6} {78-h+6} {x+6} {78-h+14} L{x+6} 78 Z',f,DK,1.5)
def sack(f,mark=None):return P('M26 34 Q30 26 48 26 Q66 26 70 34 L74 74 Q48 82 22 74 Z',f,DK,2)+P('M38 26 L44 18 L52 18 L58 26','none',DK,2)+(mark or '')
def box(x,y,w,h,f):return R(x,y,w,h,f,3,DK,2)+L(x,y+h*.35,x+w,y+h*.35,DK,1.5)
def cyl(x,y,w,h,f,cap):return R(x,y+6,w,h-6,f,w/2.4)+R(x+w*.25,y,w*.5,10,cap,2)
def car(f,y=50):return P(f'M16 {y+16} L16 {y+4} Q18 {y-2} 28 {y-2} L36 {y-14} Q40 {y-18} 48 {y-18} L62 {y-18} Q68 {y-18} 72 {y-10} L78 {y-2} Q82 {y} 82 {y+6} L82 {y+16} Z',f,DK,2)+P(f'M40 {y-12} L48 {y-12} L48 {y-2} L34 {y-2} Z',BLU)+P(f'M52 {y-12} L62 {y-12} L68 {y-2} L52 {y-2} Z',BLU)+C(32,y+16,7,BLK)+C(32,y+16,3,MET2)+C(68,y+16,7,BLK)+C(68,y+16,3,MET2)
def truckcab(f):return P('M24 74 L24 34 Q24 24 34 22 L62 22 Q70 22 70 30 L70 74 Z',f,DK,2)+R(30,28,34,16,BLU,3)+R(28,52,40,4,DK)+C(36,76,7,BLK)+C(62,76,7,BLK)
def bale(f,s):return R(22,30,52,40,f,6,DK,2)+L(22,44,74,44,s,2)+L(22,56,74,56,s,2)+L(36,30,36,70,s,2)+L(60,30,60,70,s,2)
